#!/usr/bin/env python3
"""Fails CI when any logic file in the app has less test coverage than the minimum.

Screens (*View.swift) are covered by UI tests, generated models by the schema check,
and the live network glue by scripts/check-live-ai.sh, so they are listed as exempt.
Usage: coverage-gate.py <path to .xcresult>
"""
import json
import subprocess
import sys

MINIMUM = 0.85
EXEMPT_SUFFIXES = ("View.swift",)
EXEMPT_FILES = {
    "GinkgoModels.swift": "generated by quicktype; checked against the schema",
    "GinkgoApp.swift": "app entry point; exercised by every launch",
    "GeminiClient.swift": "network glue; covered by scripts/check-live-ai.sh",
    "DepthCapture.swift": "ARKit session glue; needs LiDAR, checked on a real iPhone",
    "MeshCapture.swift": "ARKit mesh glue; needs LiDAR, checked on a real iPhone",
    "CameraPreview.swift": "ARKit camera view; needs LiDAR, checked on a real iPhone",
}

report = json.loads(subprocess.check_output(["xcrun", "xccov", "view", "--report", "--json", sys.argv[1]]))
app = next(t for t in report["targets"] if t["name"] == "Ginkgo.app")

failures, checked = [], []
for f in app["files"]:
    name = f["name"]
    if name in EXEMPT_FILES or name.endswith(EXEMPT_SUFFIXES):
        continue
    checked.append((name, f["lineCoverage"]))
    if f["lineCoverage"] < MINIMUM:
        failures.append((name, f["lineCoverage"]))

for name, cov in sorted(checked):
    print(f"  {'FAIL' if cov < MINIMUM else 'ok  '} {cov:6.1%}  {name}")
if not checked:
    sys.exit("Coverage gate found no logic files to check")
if failures:
    sys.exit(f"Coverage below {MINIMUM:.0%} in: " + ", ".join(n for n, _ in failures))
print(f"All {len(checked)} logic files at or above {MINIMUM:.0%}.")
